def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """

    # Check if prior is an InventoryValidator object
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator object")

    # Check if prior is a prior version of the current inventory
    if not prior.version < self.version:
        raise ValueError("prior must be a prior version of the current inventory")

    # Check if all objects present in prior are also present in current
    prior_objects = prior.objects
    current_objects = self.objects
    for obj_id in prior_objects:
        if obj_id not in current_objects:
            raise ValueError("prior is not a prior version of the current inventory")

    # Check if all object versions in prior are consistent with current
    for obj_id in prior_objects:
        if prior_objects[obj_id] != current_objects[obj_id]:
            raise ValueError("prior is not a prior version of the current inventory")

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for file in inventory.files:
        if file.version == version:
            logical_path_map.setdefault(file.logical_path, set()).add(file.physical_path)
    for file in inventory.duplicates:
        if file.version == version:
            for logical_path in logical_path_map.keys():
                if logical_path in file.logical_paths:
                    logical_path_map[logical_path].add(file.physical_path)
    return logical_path_map

