        pattern = '(["\'])(?:(?=(\\?))\2.)*?\1|(\\\\.|[^\\s"\'])+\n*|["\'][^\n]*["\']'
    elif platform == 'Windows/CMD':
        pattern = '(["\'])(?:(?=(\\?))\2.)*?\1|(?:\\\\.|[^"\s^&|<^>])+'
    else:
        raise ValueError('Invalid platform')

    matches = re.findall(pattern, s)
    result = []

    for match in matches:
        if match[0] == '"' or match[0] == "'":
            result.append(match[0])
        else:
            result.append(match[0])

    return result

