def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, (str, list, tuple)):
        raise TypeError("commands argument must be a string, list, or tuple")
    if not isinstance(args, (str, list, tuple)):
        raise TypeError("args argument must be a string, list, or tuple")

    if isinstance(commands, (list, tuple)):
        commands = " ".join(commands)
    if isinstance(args, (list, tuple)):
        args = " ".join(args)

    command = "%s %s" % (commands, args)

    process = subprocess.Popen(command, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
    output, error = process.communicate()

    if process.returncode != 0:
        if hide_stderr:
            error = ""
        raise CalledProcessError(process.returncode, command, output=output, stderr=error)

    if verbose:
        print("Command: %s" % command)
        print("Output: %s" % output.decode("utf-8"))
        if error:
            print("Error: %s" % error.decode("utf-8"))

    return output.decode("utf-8")

