def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that candidate might correctly provide a given interface.

    This involves:
    - Making sure the candidate claims that it provides the interface using `iface.providedBy` (unless `tentative` is `True`, in which case this step is skipped).
    - Making sure the candidate defines all the necessary methods.
    - Making sure the methods have the correct signature (to the extent possible).
    - Making sure the candidate defines all the necessary attributes.

    :return bool: Returns a true value if everything that could be checked passed.
    :raises zope.interface.Invalid: If any of the previous conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors are collected and reported. Previously, only the first error was reported. As a special case, if only one such error is present, it is raised alone, like before.
    """
    if not isinstance(iface, Interface):
        raise TypeError(f"{type(iface)} is not an Interface.")
    valid = True
    if not tentative and not iface.providedBy(candidate):
        raise Invalid(
            f"The provided object does not provide the interface {iface.getId()}."
        )
    for name, attr in iface.getNamesAndAttributes():
        if not isinstance(attr, Attribute):
            continue
        if not hasattr(candidate, name):
            raise Invalid(
                f"The provided object does not define the attribute {name}."
            )
        valid &= attr.verify(getattr(candidate, name))

    for method in iface.getNamesAndMethods():
        if not isinstance(method, Method):
            continue
        if not hasattr(candidate, method.getId()):
            raise Invalid(
                f"The provided object does not define the method { method.getId()}."
            )
        verify(method.getId(), method.getSignature(), candidate)

    return valid

