def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if self.cache_len == 0:
        raise KeyError("popitem(): cache is empty")
    key, value = None, None
    for k, v in self.cache.items():
        if key is None or v[1] < self.cache[k][1]:
            key, value = k, self.cache[k][0]
    del self.cache[key]
    self.cache_len -= 1
    return key, value

