    """Process links in text, adding some attributes and linkifying textual links."""
    # Add necessary attributes to <a> elements
    for link in text.find_all("a"):
        if not link.has_attr("target"):
            link["target"] = "_blank"
        if not link.has_attr("rel"):
            link["rel"] = "noopener noreferrer"

    # Linkify textual links
    for match in re.findall(r"\b(https?://\S+)\b", text):
        url = match.group(1)
        display_url = url.split("/")[2].split("?")[0]
        display_url = display_url[:20] + "..." if len(display_url) > 20 else display_url
        link = f'<a href="{url}" target="_blank" rel="noopener noreferrer">{display_url}</a>'
        text = text.replace(match, link)

    return text

