def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if document.startswith('{'):
        # JSON format
        try:
            data = json.loads(document)
        except json.JSONDecodeError:
            raise ValueError("Invalid JSON")
        if 'links' not in data:
            raise ValueError("Missing 'links' element")
        links = data['links']
        if not links:
            raise ValueError("No links found")
        if not all(isinstance(link, dict) for link in links):
            raise ValueError("Invalid link data")
        result = {}
        for link in links:
            href = link.get('href')
            if not href:
                continue
            if 'rel' not in link:
                continue
            if link['rel'] == 'diaspora-admin':
                result['diaspora_admin'] = href
            elif link['rel'] == 'diaspora-redirection':
                result['diaspora_redirection'] = href
            elif link['rel'] == 'diaspora-activity':
                result['diaspora_activity'] = href
            elif link['rel'] == 'diaspora-messages':
                result['diaspora_messages'] = href
            elif link['rel'] == 'diaspora-spam':
                result['diaspora_spam'] = href
            elif link['rel'] == 'diaspora-search':
                result['diaspora_search'] = href
            elif link['rel'] == 'diaspora-search-results':
                result['diaspora_search_results'] = href
            else:
                raise ValueError("Invalid link relationship")
        return result
    else:
        # XRD format
        raise NotImplementedError("XRD format not supported yet")

